11	import { deleteJotaiStorageAdapter } from "modules/storage/utils";
12	import RNFS from "react-native-fs";
13	import { clearImageCache } from "shared/utils/image-caching";
14	import { MatrixStorage } from "../../matrix-client/const";
15	import { MatrixJotaiStore } from "../../matrix-client/const/matrx-jotai-store";
16	import { MatrixAtoms, resetMatrixAtoms } from "../../matrix-client/jotai";
17	import { MatrixCore } from "../../matrix-client/services/MatrixCore";
18	import { PushNotificationsAtoms } from "../../push-notifications/jotai";
19	import { MatrixNotificationService } from "../../push-notifications/service/MatrixNotificationService";
20	
21	type LoginWithUsernameAndPasswordData = {
22	  username: string;
23	  password: string;
24	};
25	
26	const dataPath = `${RNFS.DocumentDirectoryPath}/matrix/data`;
27	const cachePath = `${RNFS.CachesDirectoryPath}/matrix/cache`;
28	
29	export class AuthService {
30	  private static async clearCryptoStore() {
31	    try {
32	      const dataExists = await RNFS.exists(dataPath);
33	      const cacheExists = await RNFS.exists(cachePath);
34	
35	      if (dataExists) {
36	        await RNFS.unlink(dataPath);
37	        console.log("Cleared crypto data store");
38	      }
39	
40	      if (cacheExists) {
41	        await RNFS.unlink(cachePath);
42	        console.log("Cleared crypto cache store");
43	      }
44	    } catch (error) {
45	      console.warn("Failed to clear crypto store:", error);
46	    }
47	  }
48	
49	  /** Full init for first login — does server discovery (requires network). */
50	  public static initialize = async (serverUrl: string) => {
51	    MatrixCore.instance = await new ClientBuilder()
52	      .serverNameOrHomeserverUrl(serverUrl)
53	      .sessionPaths(dataPath, cachePath)
54	      .autoEnableCrossSigning(true)
55	      .autoEnableBackups(false)
56	      .backupDownloadStrategy(BackupDownloadStrategy.AfterDecryptionFailure)
57	      .build();
58	  };
59	
60	  /**
61	   * Offline-capable init for session restore.
62	   * Uses the exact homeserver URL + known username so no server discovery is needed.
63	   */
64	  private static initializeForRestore = async (
65	    homeserverUrl: string,
66	    userId: string,
67	  ) => {
68	    MatrixCore.instance = await new ClientBuilder()
69	      .homeserverUrl(homeserverUrl)
70	      .username(userId)
71	      .slidingSyncVersionBuilder(SlidingSyncVersionBuilder.Native)
72	      .sessionPaths(dataPath, cachePath)
73	      .autoEnableCrossSigning(true)
74	      .autoEnableBackups(false)
75	      .backupDownloadStrategy(BackupDownloadStrategy.AfterDecryptionFailure)
76	      .build();
77	  };
78	
79	  public static hasStoredCredentials = (): boolean => {
80	    return MatrixStorage.hasStoredCredentials();
81	  };
82	
83	  public static getServerName = () => MatrixCore.getServerName();
84	
85	  public static getUser = () => {
86	    if (!MatrixCore.instance) return null;
87	    const userId = MatrixCore.instance.userId();
88	    return userId ? MatrixCore.instance.getProfile(userId) : null;
89	  };
90	
91	  public static restoreSessionForBackground = async (): Promise<boolean> => {
92	    try {
93	      if (
94	        MatrixCore.instance &&
95	        MatrixNotificationService.getNotificationClient()
96	      )
97	        return true;
98	
99	      const credentials = MatrixStorage.getLoginCredentials();
100	      if (!credentials) return false;
101	
102	      // Use the same offline-safe init as foreground so the client is compatible
103	      // if the foreground reuses this instance (same file paths, same sync config).
104	      await this.initializeForRestore(credentials.baseUrl, credentials.userId);
105	
106	      const client = MatrixCore.getClient();
107	
108	      await client.restoreSession({
109	        accessToken: credentials.accessToken,
110	        refreshToken: credentials.refreshToken,
111	        userId: credentials.userId,
112	        deviceId: credentials.deviceId,
113	        homeserverUrl: credentials.baseUrl,
114	        oidcData: undefined,
115	        slidingSyncVersion: SlidingSyncVersion.Native,
116	      });
117	
118	      await client.encryption().waitForE2eeInitializationTasks();
119	
120	      await MatrixNotificationService.ensureNotificationClient();
121	
122	      return true;
123	    } catch (error) {
124	      console.error("[Background] Failed to restore session:", error);
125	      return false;
126	    }
127	  };
128	
129	  public static restoreSession = async (): Promise<boolean> => {
130	    try {
131	      const credentials = MatrixStorage.getLoginCredentials();
132	      if (!credentials) return false;
133	
134	      // If the background handler already initialized and restored the client,
135	      // reuse it — creating a second client on the same file paths would
136	      // conflict with the existing native SDK file locks and cause a hang.
137	      if (!MatrixCore.instance) {
138	        // Use offline-capable init: direct homeserver URL + known username,
139	        // no server discovery needed.
140	        await this.initializeForRestore(
141	          credentials.baseUrl,
142	          credentials.userId,
143	        );
144	
145	        const client = MatrixCore.getClient();
146	
147	        await client.restoreSession({
148	          accessToken: credentials.accessToken,
149	          refreshToken: credentials.refreshToken,
150	          userId: credentials.userId,
151	          deviceId: credentials.deviceId,
152	          homeserverUrl: credentials.baseUrl,
153	          oidcData: undefined,
154	          slidingSyncVersion: SlidingSyncVersion.Native,
155	        });
156	      }
157	
158	      const client = MatrixCore.getClient();
159	
160	      // Profile fetch may fail when offline — don't block session restore on it.
161	      try {
162	        const profile = await client.getProfile(credentials.userId);
163	        MatrixJotaiStore.set(StorageAtoms.cachedProfile, profile);
164	      } catch {}
165	
166	      // withOfflineMode() serves cached rooms immediately without waiting for network.
167	      MatrixCore.syncService = await client
168	        .syncService()
169	        .withOfflineMode()
170	        .finish();
171	
172	      if (!MatrixCore.syncService) {
173	        throw new Error("Failed to initialize sync service");
174	      }
175	
176	      MatrixJotaiStore.set(MatrixAtoms.matrixClient, MatrixCore.instance);
177	      MatrixJotaiStore.set(MatrixAtoms.syncService, MatrixCore.syncService);
178	
179	      return true;
180	    } catch (error) {
181	      console.warn("Failed to restore session:", error);
182	
183	      MatrixCore.instance = null;
184	      MatrixCore.syncService = null;
185	
186	      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
187	      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
188	
189	      return false;
190	    }
191	  };
192	
193	  /** Start (or resume) the Matrix sync loop. No-op if the sync service is not ready. */
194	  public static startSync = async (): Promise<void> => {
195	    if (!MatrixCore.syncService) return;
196	    try {
197	      await MatrixCore.syncService.start();
198	    } catch (error) {
199	      console.warn("Failed to start sync:", error);
200	    }
201	  };
202	
203	  /** Stop the Matrix sync loop. No-op if the sync service is not ready. */
204	  public static stopSync = async (): Promise<void> => {
205	    if (!MatrixCore.syncService) return;
206	    try {
207	      await MatrixCore.syncService.stop();
208	    } catch (error) {
209	      console.warn("Failed to stop sync:", error);
210	    }
211	  };
212	
213	  public static setup = async (params: Session) => {
214	    await this.clearCryptoStore();
215	
216	    if (MatrixCore.syncService) await MatrixCore.syncService.stop();
217	    MatrixCore.instance = null;
218	    MatrixCore.syncService = null;
219	
220	    MatrixStorage.saveLoginCredentials({
221	      accessToken: params.accessToken,
222	      refreshToken: params.refreshToken,
223	      userId: params.userId,
224	      deviceId: params.deviceId,
225	      baseUrl: params.homeserverUrl,
226	    });
227	
228	    await this.initialize(params.homeserverUrl);
229	
230	    const client = MatrixCore.getClient();
231	
232	    await client.restoreSession({
233	      accessToken: params.accessToken,
234	      refreshToken: params.refreshToken,
235	      userId: params.userId,
236	      deviceId: params.deviceId,
237	      homeserverUrl: params.homeserverUrl,
238	      oidcData: undefined,
239	      slidingSyncVersion: SlidingSyncVersion.Native,
240	    });
241	
242	    try {
243	      const profile = await client.getProfile(params.userId);
244	      MatrixJotaiStore.set(StorageAtoms.cachedProfile, profile);
245	    } catch (error) {
246	      console.warn("Session validation failed:", error);
247	    }
248	
249	    MatrixCore.syncService = await client.syncService().finish();
250	
251	    if (!MatrixCore.syncService) {
252	      throw new Error("Failed to initialize sync service");
253	    }
254	
255	    await MatrixCore.syncService.start();
256	    await client.encryption().waitForE2eeInitializationTasks();
257	
258	    MatrixJotaiStore.set(MatrixAtoms.matrixClient, MatrixCore.instance);
259	    MatrixJotaiStore.set(MatrixAtoms.syncService, MatrixCore.syncService);
260	  };
261	
262	  public static login = async ({
263	    username,
264	    password,
265	  }: LoginWithUsernameAndPasswordData) => {
266	    const client = MatrixCore.getClient();
267	    await client.login(username, password, undefined, undefined);
268	    const session = client.session();
269	
270	    MatrixCore.instance = null;
271	
272	    return session;
273	  };
274	
275	  public static logout = async () => {
276	    // Remove pusher before clearing the session — needs an active Matrix client.
277	    // Ignore errors (user may be offline or permissions already revoked).
278	    const fcmToken = MatrixJotaiStore.get(PushNotificationsAtoms.token);
279	    if (fcmToken) {
280	      try {
281	        await MatrixNotificationService.removePusher(fcmToken);
282	      } catch {}
283	    }
284	
285	    MatrixStorage.clearLoginCredentials();
286	    deleteJotaiStorageAdapter();
287	    await this.clearCryptoStore();
288	    await clearImageCache();
289	
290	    //Ignore both errors if it happens, the logout will still happen. These errors can happen if the user is offline.
291	    if (MatrixCore.syncService) {
292	      try {
293	        await MatrixCore.syncService.stop();
294	      } catch {}
295	    }
296	    if (MatrixCore.instance) {
297	      try {
298	        await MatrixCore.instance.logout();
299	      } catch {}
300	    }
301	
302	    MatrixCore.instance = null;
303	    MatrixCore.syncService = null;
304	
